changeSet.sql:
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_schema = 'public'
          AND table_name = 'users'
          AND column_name = 'id'
          AND is_identity = 'YES'
    ) THEN
        ALTER TABLE users
            ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
    END IF;

    PERFORM setval(
        pg_get_serial_sequence('users', 'id'),
        COALESCE((SELECT max(id) FROM users), 0) + 1,
        false
    );
END $$;
